query:
query GetFormFlowBySlug($slug: String!) {
  getFormFlowBySlug(slug: $slug) {
    success
    message
    data {
      ...FlexFormFlowFragment
      __typename
    }
    __typename
  }
}

fragment FlexFormFlowFragment on FlexFormFlow {
  id
  slug
  description
  isActive
  isDefault
  pathPatterns
  createdAt
  updatedAt
  flowDefinition {
    ...FlowDefinitionFragment
    __typename
  }
  __typename
}

fragment FlowDefinitionFragment on FlowDefinition {
  startNodeId
  metadata {
    ...FlowMetadataFragment
    __typename
  }
  nodes {
    ... on StartNodeConfig {
      ...StartNodeConfigFragment
      __typename
    }
    ... on FormNodeConfig {
      ...FormNodeConfigFragment
      __typename
    }
    ... on ContentNodeConfig {
      ...ContentNodeConfigFragment
      __typename
    }
    ... on DecisionNodeConfig {
      ...DecisionNodeConfigFragment
      __typename
    }
    ... on FieldConditionValidationNodeConfig {
      ...FieldConditionValidationNodeConfigFragment
      __typename
    }
    ... on ChilipiperCalendarNodeConfig {
      ...ChilipiperCalendarNodeConfigFragment
      __typename
    }
    ... on ConfirmationNodeConfig {
      ...ConfirmationNodeConfigFragment
      __typename
    }
    ... on EndNodeConfig {
      ...EndNodeConfigFragment
      __typename
    }
    ... on SlackSyncNodeConfig {
      ...SlackSyncNodeConfigFragment
      __typename
    }
    ... on HubspotSyncNodeConfig {
      ...HubspotSyncNodeConfigFragment
      __typename
    }
    ... on PosthogSyncNodeConfig {
      ...PosthogSyncNodeConfigFragment
      __typename
    }
    ... on SetFieldNodeConfig {
      ...SetFieldNodeConfigFragment
      __typename
    }
    ... on CompleteCalendarBookingNodeConfig {
      ...CompleteCalendarBookingNodeConfigFragment
      __typename
    }
    ... on MarkFlowCompleteNodeConfig {
      ...MarkFlowCompleteNodeConfigFragment
      __typename
    }
    ... on TriggerFeEventsNodeConfig {
      ...TriggerFeEventsNodeConfigFragment
      __typename
    }
    __typename
  }
  __typename
}

fragment FlowMetadataFragment on FormFlowMetadata {
  requiredFlowFields
  showProgress
  consentExemptFieldIds
  __typename
}

fragment StartNodeConfigFragment on StartNodeConfig {
  id
  internalName
  type
  internalDescription
  externalHeader
  externalSubHeader
  nextNodeId
  displayConfig {
    nextLabel
    previousLabel
    __typename
  }
  preventPreviousAction
  __typename
}

fragment FormNodeConfigFragment on FormNodeConfig {
  id
  internalName
  type
  internalDescription
  externalHeader
  externalSubHeader
  nextNodeId
  displayConfig {
    nextLabel
    previousLabel
    __typename
  }
  preventPreviousAction
  fields {
    id
    label
    required
    display {
      width
      prefixBlankSpace
      blankSpaceWidth
      supportText
      smallLabel
      __typename
    }
    conditionals {
      fieldId
      operator
      value
      action
      __typename
    }
    validations {
      message
      conditions {
        fieldId
        operator
        value
        __typename
      }
      __typename
    }
    __typename
  }
  __typename
}

